# Every game owns one cancellable timer; old callbacks cannot restart a reset game.
def game_pause(app):
    app.running = False
    app.generation += 1
    if app.timer is not None:
        app.root.after_cancel(app.timer)
        app.timer = None

def game_tick(app, generation):
    if not app.running or generation != app.generation:
        return
    app.timer = None
    game_step(app)
    game_draw(app)
    if app.running and generation == app.generation:
        app.timer = app.root.after(60, lambda: game_tick(app, generation))

def game_start(app):
    if app.running or app.over:
        return
    app.running = True
    app.generation += 1
    app.Board.focus_set()
    game_tick(app, app.generation)

def game_close(app):
    game_pause(app)
    app.root.destroy()

# A compact original level demonstrates gravity, landing, jumping and a goal.
PLATFORMS = [(0,500,180,520),(205,425,330,445),(355,345,480,365),(490,265,595,285)]
def game_reset(app):
    game_pause(app)
    app.x = 40.0; app.y = 470.0; app.vy = 0.0; app.dx = 0; app.grounded = True; app.won = False; app.over = False
    game_draw(app)

def platform_move(app, dx):
    if app.running:
        app.dx = dx

def platform_jump(app):
    if app.running and app.grounded:
        app.vy = -15; app.grounded = False

def game_step(app):
    old_bottom = app.y + 25
    app.x = max(0, min(575, app.x + app.dx))
    app.vy = min(18, app.vy + 0.85); app.y += app.vy; app.grounded = False
    for left,top,right,bottom in PLATFORMS:
        if app.vy >= 0 and old_bottom <= top and app.y+25 >= top and app.x+25 > left and app.x < right:
            app.y = top-25; app.vy = 0; app.grounded = True
            break
    app.won = app.x > 545 and app.y < 265
    app.over = app.won or app.y > 540
    if app.over:
        game_pause(app)

def game_draw(app):
    c = app.Board; c.delete('all')
    for platform in PLATFORMS:
        c.create_rectangle(*platform,fill='#69c49d',outline='')
    c.create_rectangle(560,205,580,265,fill='#ffd166')
    c.create_rectangle(app.x,app.y,app.x+25,app.y+25,fill='#76beff')
    text = ('Goal reached!' if app.won else 'Fell! Reset to retry.') if app.over else 'Hold Left/Right; Space jumps. Side buttons set motion; Stop halts it.'
    app.Status.configure(text=text)
